
select distinct substr("ORDER_ACTIVITY"."ORDER_LINE_ID", 1, 5) "Order_Company", "SALES_ORDER_LEDGER"."ORDER_NUMBER" "Order_Number", substr("SALES_ORDER_LEDGER"."ORDER_LINE_ID", 1+instr("SALES_ORDER_LEDGER"."ORDER_LINE_ID", ',', -1), 5) "Line_Number", "SALES_ORDER_LEDGER_MEASURES"."ITEM_NUMBER_2ND" "C_2nd_Item_Number", "SALES_ORDER_LEDGER_MEASURES"."ORDERED_DATE" "Ordered_Date", "SALES_ORDER_LEDGER"."DATE_CREATED" "Date_Created", "SALES_ORDER_LEDGER_MEASURES"."LAST_STATUS" "Last_Status", "SALES_ORDER_LEDGER_MEASURES"."NEXT_STATUS" "Next_Status", "SALES_ORDER_LEDGER"."ORDER_LINE_LAST_UPDATED" "Order_Line_Last_Updated", "SALES_ORDER_LEDGER"."ORDER_LINE_LAST_UPDATED_BY" "Order_Line_Last_Updated_By"
 from "DW_LEGACY"."ORDER_ACTIVITY" "ORDER_ACTIVITY", "DW_LEGACY"."SALES_ORDER_LEDGER" "SALES_ORDER_LEDGER", "DW_LEGACY"."SALES_ORDER_LEDGER_MEASURES" "SALES_ORDER_LEDGER_MEASURES", "DW_LEGACY"."ITEM" "ITEM", "DW_LEGACY"."ORDER_ACTIVITY_MEASURES" "ORDER_ACTIVITY_MEASURE"
 where "SALES_ORDER_LEDGER_MEASURES"."ORDERED_DATE">=DATE '2024-01-01' and substr("ORDER_ACTIVITY"."ORDER_LINE_ID", 1, 5)='00010' and "SALES_ORDER_LEDGER_MEASURES"."NEXT_STATUS" in (N'520', N'525', N'530') and "SALES_ORDER_LEDGER"."ORDER_LINE_LAST_UPDATED_BY" not  in (N'SCHED') and decode("ITEM"."GLOBAL_BULK_ITEM", '-', "ORDER_ACTIVITY_MEASURE"."ITEM_NUMBER_2ND", "ITEM"."GLOBAL_BULK_ITEM") not  in ('IGST', 'CGST', 'SGST', 'CVD', 'ADD') and "ORDER_ACTIVITY"."ORDER_ACTIVITY_SID"="ORDER_ACTIVITY_MEASURE"."ORDER_ACTIVITY_SID" and "ORDER_ACTIVITY_MEASURE"."ORDER_ACTIVITY__ITEM_SID"="ITEM"."ITEM_SID" and "SALES_ORDER_LEDGER"."ORDER_LINE_ID"="ORDER_ACTIVITY"."JDE_ORDER_LINE_ID" and "SALES_ORDER_LEDGER"."SALES_ORDER_LEDGER_SID"="SALES_ORDER_LEDGER_MEASURES"."SALES_ORDER_LEDGER_SID"
 order by "Order_Number" asc nulls last, "Order_Line_Last_Updated" asc nulls last, "Line_Number" asc nulls last



